// Explicit old-schema financial fixtures. Never used by production routes.
import type pg from 'pg';
import type {Actor} from '../../server/services';
import {randomUUID,createHash} from 'node:crypto';
const hash=(v:unknown)=>createHash('sha256').update(JSON.stringify(v)).digest('hex');
export async function legacyReceipt(db:pg.PoolClient,a:Actor,i:any){const id=randomUUID();let total=0;const lines=[];for(const l of i.lines){const u=(await db.query('SELECT factor FROM units WHERE id=$1',[l.unit_id])).rows[0];const gross=l.quantity*l.unit_cost_paisa;total+=gross;lines.push({...l,factor:u.factor,gross});}await db.query('INSERT INTO purchases(id,branch_id,supplier_id,vendor_ref,idempotency_key,request_hash,total_paisa,actor_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[id,a.branch_id,i.supplier_id,i.vendor_ref,i.idempotency_key,hash(i),total,a.id]);for(const l of lines){const batch=randomUUID();await db.query('INSERT INTO batches(id,branch_id,medicine_id,purchase_id,batch_code,expiry,quantity,cost_paisa) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[batch,a.branch_id,l.medicine_id,id,l.batch_code,l.expiry,l.quantity*l.factor,l.unit_cost_paisa/l.factor]);await db.query('INSERT INTO purchase_lines(id,purchase_id,batch_id,unit_id,quantity,quantity_base,unit_cost_paisa) VALUES($1,$2,$3,$4,$5,$6,$7)',[randomUUID(),id,batch,l.unit_id,l.quantity,l.quantity*l.factor,l.unit_cost_paisa]);await db.query("INSERT INTO movements(id,branch_id,batch_id,quantity_base,type,reference_id,actor_id,reason) VALUES($1,$2,$3,$4,'RECEIPT',$5,$6,'Historical fixture')",[randomUUID(),a.branch_id,batch,l.quantity*l.factor,id,a.id]);}await db.query('INSERT INTO supplier_entries(id,branch_id,supplier_id,purchase_id,amount_paisa) VALUES($1,$2,$3,$4,$5)',[randomUUID(),a.branch_id,i.supplier_id,id,total]);return id;}
export async function legacySale(db:pg.PoolClient,a:Actor,i:any){const id=randomUUID(),lines=[];let total=0;for(const l of i.lines){const m=(await db.query('SELECT m.name,u.name unit_name,u.factor,u.price_paisa FROM medicines m JOIN units u ON u.medicine_id=m.id WHERE m.id=$1 AND u.id=$2',[l.medicine_id,l.unit_id])).rows[0],b=(await db.query('SELECT *,expiry::text expiry_text FROM batches WHERE medicine_id=$1 ORDER BY expiry,id FOR UPDATE',[l.medicine_id])).rows[0];const quantity=l.quantity*m.factor,gross=l.quantity*Number(m.price_paisa);if(quantity>b.quantity)throw Error('Historical fixture quantity');total+=gross;lines.push({...l,...m,b,quantity_base:quantity,gross});}const shift=(await db.query('SELECT id FROM shifts WHERE cashier_id=$1 ORDER BY opened_at DESC LIMIT 1',[a.id])).rows[0];await db.query('INSERT INTO sales(id,branch_id,number,idempotency_key,request_hash,actor_id,subtotal_paisa,discount_paisa,tax_paisa,total_paisa,change_paisa,shift_id) VALUES($1,$2,$3,$4,$5,$6,$7,0,0,$7,0,$8)',[id,a.branch_id,'HIST-'+id,i.idempotency_key,hash(i),a.id,total,shift?.id||null]);for(const l of lines){const line=randomUUID();await db.query("INSERT INTO sale_lines(id,sale_id,medicine_id,medicine_name,description,unit_name,factor,quantity,price_paisa,cost_paisa,total_paisa) VALUES($1,$2,$3,$4,'Historical fixture',$5,$6,$7,$8,$9,$10)",[line,id,l.medicine_id,l.name,l.unit_name,l.factor,l.quantity,l.price_paisa,l.quantity_base*Number(l.b.cost_paisa),l.gross]);await db.query('UPDATE batches SET quantity=quantity-$1 WHERE id=$2',[l.quantity_base,l.b.id]);await db.query('INSERT INTO allocations(id,line_id,batch_id,batch_code,expiry,quantity_base,cost_paisa) VALUES($1,$2,$3,$4,$5,$6,$7)',[randomUUID(),line,l.b.id,l.b.batch_code,l.b.expiry_text,l.quantity_base,l.b.cost_paisa]);await db.query("INSERT INTO movements(id,branch_id,batch_id,quantity_base,type,reference_id,actor_id,reason) VALUES($1,$2,$3,$4,'SALE',$5,$6,'Historical fixture')",[randomUUID(),a.branch_id,l.b.id,-l.quantity_base,id,a.id]);}await db.query("INSERT INTO payments(id,sale_id,method,amount_paisa) VALUES($1,$2,'CASH',$3)",[randomUUID(),id,total]);return id;}
